    #[test]
    fn section_anchors_are_unique() {
        // `section_anchor` is lossy — `[]` and `.` both collapse to `-` — so two
        // section names can slug to one anchor. Two headings sharing an id means
        // every link to it silently resolves to whichever one the renderer emits
        // first, and nothing reports it. The anchors are counted because a set
        // would hide a duplicate.
        let md = generate_config_reference(&load_templates()).expect("render");
        let emitted: Vec<&str> = md
            .lines()
            .filter(|l| l.starts_with("## "))
            .filter_map(|l| l.rsplit_once("{#"))
            .filter_map(|(_, rest)| rest.strip_suffix('}'))
            .collect();
        let distinct: std::collections::HashSet<&&str> = emitted.iter().collect();
        assert_eq!(
            emitted.len(),
            distinct.len(),
            "two section names slug to the same anchor: {:?}",
            {
                let mut dupes: Vec<&&str> = emitted
                    .iter()
                    .filter(|a| emitted.iter().filter(|b| b == a).count() > 1)
                    .collect();
                dupes.sort_unstable();
                dupes.dedup();
                dupes
            }
        );
    }

    #[test]
    fn every_generated_default_link_resolves_to_an_emitted_anchor() {
        // The whole point of emitting explicit `{#anchor}` attributes: zola
        // does not validate bare `#fragment` targets, so a link that missed
        // would be dead with nothing reporting it.
        let md = generate_config_reference(&load_templates()).expect("render");
        let anchors: std::collections::HashSet<&str> = md
            .lines()
            .filter(|l| l.starts_with("## "))
            .filter_map(|l| l.rsplit_once("{#"))
            .filter_map(|(_, rest)| rest.strip_suffix('}'))
            .collect();
        assert!(!anchors.is_empty(), "no section anchors were emitted");

        let mut linked = 0;
        for rest in md.split_terminator("[per field](#").skip(1) {
            let target = rest.split(')').next().expect("link target");
            assert!(
                anchors.contains(target),
                "dead Default-column link to #{target}"
            );
            linked += 1;
        }
        assert!(linked > 0, "no composite default was linked to a section");
    }

    #[test]
    fn collapse_description_unwraps_links_after_joining_wrapped_lines() {
        // A rustdoc link split across a hard wrap must still unwrap after
        // the paragraph joins.
        assert_eq!(
            collapse_description("layered on top of [`Self::upload_concurrency`]\n(the cap)"),
            "layered on top of `upload_concurrency` (the cap)"
        );
    }

    #[test]
    fn schema_description_flattens_paragraphs_for_table_cells() {
        // A two-paragraph rustdoc description must render as ONE table-cell
        // line: paragraph break -> <br><br>, no bare newline survives.
        let schema = serde_json::json!({
            "description": "First paragraph\nhard-wrapped here.\n\nSecond paragraph with a | pipe."
        });
        let cell = schema_description(&schema);
        assert_eq!(
            cell,
            "First paragraph hard-wrapped here.<br><br>Second paragraph with a \\| pipe."
        );
        assert!(!cell.contains('\n'));
    }

    #[test]
    fn gen_docs_filters_hidden_flags() {
        let cmd = Command::new("root").subcommand(
            Command::new("leaf")
                .arg(Arg::new("visible").long("visible").help("visible flag"))
                .arg(
                    Arg::new("hidden")
                        .long("hidden-flag")
                        .help("hidden flag")
                        .hide(true),
                ),
        );

        let commands = collect_all_commands(&cmd);
        let leaf = commands
            .iter()
            .find(|c| c.name == "leaf")
            .expect("leaf command present");
        let longs: Vec<&str> = leaf.args.iter().map(|a| a.long.as_str()).collect();
        assert!(
            longs.iter().any(|l| l.contains("visible")),
            "visible flag should be rendered: {longs:?}"
        );
        assert!(
            !longs.iter().any(|l| l.contains("hidden-flag")),
            "hidden flag must be filtered: {longs:?}"
        );
    }

    #[test]
    fn gen_docs_recurses_into_nested_subcommands() {
        let cmd = Command::new("root").subcommand(
            Command::new("parent")
                .subcommand(Command::new("child-a"))
                .subcommand(Command::new("child-b")),
        );

        let commands = collect_all_commands(&cmd);
        let names: Vec<&str> = commands.iter().map(|c| c.name.as_str()).collect();
        assert!(names.contains(&"parent"), "parent must appear: {names:?}");
        assert!(
            names.contains(&"parent child-a"),
            "nested child-a must appear: {names:?}"
        );
        assert!(
            names.contains(&"parent child-b"),
            "nested child-b must appear: {names:?}"
        );
    }

    #[test]
    fn gen_docs_excludes_hidden_subcommands() {
        let cmd = Command::new("root").subcommand(
            Command::new("parent")
                .subcommand(Command::new("visible-child"))
                .subcommand(Command::new("hidden-child").hide(true)),
        );

        let commands = collect_all_commands(&cmd);
        let names: Vec<&str> = commands.iter().map(|c| c.name.as_str()).collect();
        assert!(
            names.contains(&"parent visible-child"),
            "visible nested subcommand must appear: {names:?}"
        );
        assert!(
            !names.iter().any(|n| n.contains("hidden-child")),
            "hidden nested subcommand must be filtered: {names:?}"
        );
    }

    #[test]
    fn gen_docs_excludes_hidden_global_flags() {
        // Mirror the production filter used in `generate_cli_reference` for
        // global args.
        let cmd = Command::new("root")
            .arg(
                Arg::new("g-visible")
                    .long("g-visible")
                    .global(true)
                    .help("visible global"),
            )
            .arg(
                Arg::new("g-hidden")
                    .long("g-hidden")
                    .global(true)
                    .hide(true)
                    .help("hidden global"),
            )
            .subcommand(Command::new("leaf"));

        let global_longs: Vec<String> = cmd
            .get_arguments()
            .filter(|a| a.is_global_set() && !a.is_hide_set())
            .filter_map(|a| a.get_long().map(|l| l.to_string()))
            .collect();

        assert!(
            global_longs.iter().any(|l| l == "g-visible"),
            "visible global should appear: {global_longs:?}"
        );
        assert!(
            !global_longs.iter().any(|l| l == "g-hidden"),
            "hidden global must be filtered: {global_longs:?}"
        );
    }

